<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>Ramen</title>
<style>
  :root{ color-scheme: dark; }
  *{ margin:0; padding:0; box-sizing:border-box; }
  html,body{
    height:100%;
    background:#050406;
    overflow:hidden;
    overscroll-behavior:none;
  }
  #scene{
    position:fixed; inset:0;
    width:100%; height:100%;
    display:block;
    touch-action:none;
  }
</style>
</head>
<body>
<canvas id="scene" aria-hidden="true"></canvas>
<script>
(function(){
"use strict";

/* ============================== helpers ============================== */
const TAU = Math.PI * 2;
const clamp = (v,a,b)=> v<a?a:(v>b?b:v);
const lerp  = (a,b,t)=> a+(b-a)*t;

function mulberry32(a){
  return function(){
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(0x9E3779B9);
const rr  = (a,b)=> a + rnd()*(b-a);

/* ============================== canvas ============================== */
const cvs  = document.getElementById('scene');
const ctx  = cvs.getContext('2d');

// half-resolution offscreen buffer for steam (upscaling gives free softness)
const sc   = document.createElement('canvas');
const sctx = sc.getContext('2d');

let W=0, H=0, DPR=1;
let cx=0, cy=0, R=0, rimRY=0;      // bowl rim ellipse
let bcx=0, bcy=0, bRX=0, bRY=0;    // broth ellipse
const BROTH_SCALE = 0.90;

/* ============================== state ============================== */
const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
let reduced = mq.matches;

const pointer = {
  x: 0, y: 0,            // eased position (css px)
  tx: 0, ty: 0,          // target
  vx: 0, vy: 0,          // eased velocity
  inside: false,
  has: false
};
let lx = -0.45, ly = -0.80;   // eased key-light direction

let t = 0;                    // scene time (seconds)
let last = 0;
let raf = 0;

/* ============================== scene data (normalised) ==============================
   u,v live in rim-ellipse space:  x = cx + u*R ,  y = cy + v*rimRY
   The broth disc is centred at v = +0.10 with radius 0.90.
====================================================================================== */
const B_OFF = 0.10;

// sample a point inside the broth disc, biased toward the middle
function inBroth(bias){
  const a = rnd()*TAU;
  const rad = Math.pow(rnd(), bias||0.5) * 0.94;
  return { u: Math.cos(a)*rad*BROTH_SCALE, v: B_OFF + Math.sin(a)*rad*BROTH_SCALE };
}
// pull a point back inside the broth disc
function containUV(u,v){
  const nu = u/BROTH_SCALE, nv = (v-B_OFF)/BROTH_SCALE;
  const d = Math.hypot(nu,nv);
  if(d <= 0.94) return [u,v];
  const k = 0.94/d;
  return [nu*k*BROTH_SCALE, B_OFF + nv*k*BROTH_SCALE];
}

// --- noodles: arcs of a nest -------------------------------------------------
const noodles = [];
for(let i=0;i<20;i++){
  noodles.push({
    ou: rr(-0.26,0.26), ov: B_OFF + rr(-0.14,0.16),
    ru: rr(0.20,0.60),  rv: rr(0.26,0.78),
    a0: rr(0,TAU),      sweep: rr(1.3,3.2),
    wob: rr(0.03,0.10), wf: rr(2,5), wp: rr(0,TAU),
    w:   rr(0.019,0.030),
    ph:  rr(0,TAU),     sp: rr(0.35,0.8),
    tone: rnd(),
    z: rnd()
  });
}
noodles.sort((a,b)=> a.ov - b.ov);

// --- oil droplets ------------------------------------------------------------
const oils = [];
for(let i=0;i<62;i++){
  const p = inBroth(0.55);
  oils.push({ u:p.u, v:p.v, r: rr(0.007,0.030), ph: rr(0,TAU), sp: rr(0.10,0.30), sh: rr(0.4,1) });
}

// --- scallion rings ----------------------------------------------------------
const scallions = [];
for(let i=0;i<22;i++){
  const p = inBroth(0.7);
  scallions.push({ u:p.u, v:p.v, r: rr(0.026,0.046), rot: rr(0,TAU), ph: rr(0,TAU), sp: rr(0.5,1.1), tone: rnd() });
}

// --- sesame seeds ------------------------------------------------------------
const sesame = [];
for(let i=0;i<26;i++){
  const p = inBroth(0.6);
  sesame.push({ u:p.u, v:p.v, rot: rr(0,TAU), ph: rr(0,TAU), sp: rr(0.6,1.3), s: rr(0.7,1.15) });
}

// --- chilli crisp flakes -----------------------------------------------------
const chilli = [];
for(let i=0;i<26;i++){
  const a = rnd()*TAU, rad = Math.pow(rnd(),0.6)*0.20;
  chilli.push({ u: 0.10 + Math.cos(a)*rad, v: B_OFF + 0.44 + Math.sin(a)*rad*0.5,
                r: rr(0.008,0.020), rot: rr(0,TAU), ph: rr(0,TAU), sp: rr(0.4,0.9), hot: rnd() });
}

// --- corn kernels ------------------------------------------------------------
const corn = [];
for(let i=0;i<11;i++){
  const a = rnd()*TAU, rad = Math.pow(rnd(),0.6)*0.20;
  corn.push({ u: -0.55 + Math.cos(a)*rad, v: B_OFF - 0.06 + Math.sin(a)*rad*0.55,
              r: rr(0.026,0.036), rot: rr(-0.7,0.7), ph: rr(0,TAU), sp: rr(0.5,1.0) });
}

// --- ceramic speckle ---------------------------------------------------------
const speckle = [];
for(let i=0;i<90;i++){
  speckle.push({ u: rr(-1.05,1.05), y: rr(0,0.95), r: rr(0.0015,0.005), a: rr(0.02,0.10) });
}

// --- ripples -----------------------------------------------------------------
const ripples = [];
let nextAuto = 1.2;
function addRipple(u,v,strength){
  if(ripples.length > 26) ripples.shift();
  ripples.push({ u, v, t0: t, life: rr(2.6,3.6), s: strength });
}
// vertical bob contributed by passing ripples, in v-units
function rippleAt(u,v){
  let d = 0;
  for(let i=0;i<ripples.length;i++){
    const rp = ripples[i];
    const age = t - rp.t0;
    if(age < 0 || age > rp.life) continue;
    const front = age * 0.46;
    const dist = Math.hypot(u - rp.u, (v - rp.v) * 0.62);
    const dd = dist - front;
    if(Math.abs(dd) > 0.16) continue;
    const env = (1 - age/rp.life) * (1 - Math.abs(dd)/0.16);
    d += Math.sin(dd * 34) * env * 0.030 * rp.s;
  }
  return d;
}

/* ============================== steam ============================== */
function makePuff(col){
  const s = 128;
  const c = document.createElement('canvas'); c.width = c.height = s;
  const x = c.getContext('2d');
  const g = x.createRadialGradient(s/2,s/2,0,s/2,s/2,s/2);
  g.addColorStop(0.00,'rgba('+col+',0.60)');
  g.addColorStop(0.28,'rgba('+col+',0.26)');
  g.addColorStop(0.62,'rgba('+col+',0.070)');
  g.addColorStop(1.00,'rgba('+col+',0)');
  x.fillStyle = g; x.fillRect(0,0,s,s);
  return c;
}
const puffWarm = makePuff('255,200,142');
const puffCool = makePuff('186,201,224');

const MAX_PUFFS = 300;
const puffs = [];
let spawnAcc = 0;

function spawnPuff(){
  if(puffs.length >= MAX_PUFFS) return;
  const p = inBroth(0.45);
  const x = (cx + p.u * R) * 0.5;
  const y = (cy + p.v * rimRY) * 0.5;
  puffs.push({
    x, y,
    vx: rr(-4,4),
    vy: rr(-30,-16),
    r:  rr(5,13),
    grow: rr(5.5,13),
    life: rr(3.4,6.4),
    age: 0,
    seed: rr(0,TAU),
    spin: rr(-1,1),
    warm: rr(0.75,1)
  });
}

function stepSteam(dt){
  // emission
  spawnAcc += dt * 52;
  while(spawnAcc >= 1){ spawnPuff(); spawnAcc -= 1; }

  const mx = pointer.x * 0.5, my = pointer.y * 0.5;
  const mActive = pointer.has && !reduced;
  const windX = clamp(pointer.vx * 0.010, -14, 14);

  for(let i = puffs.length - 1; i >= 0; i--){
    const p = puffs[i];
    p.age += dt;
    if(p.age >= p.life){ puffs.splice(i,1); continue; }

    const k = p.age / p.life;

    // convective flow field — slow horizontal curl that widens with height
    const swirl = Math.sin(p.y * 0.017 + t * 0.55 + p.seed) * 7
                + Math.sin(p.y * 0.006 - t * 0.31 + p.seed * 1.7) * 11;
    p.vx += (swirl * (0.25 + k * 0.9) + windX - p.vx) * dt * 0.85;

    // rises fast, then cools and slows
    p.vy += (-6 - p.vy * 0.55) * dt * (0.5 + k);
    p.vy *= (1 - dt * 0.28);

    // pointer pushes and swirls the plume
    if(mActive){
      const dx = p.x - mx, dy = p.y - my;
      const d  = Math.hypot(dx,dy);
      const rad = 95;
      if(d < rad && d > 0.001){
        const f = (1 - d/rad);
        const f2 = f * f;
        p.vx += ( dx/d * 190 + -dy/d * 130) * f2 * dt;
        p.vy += ( dy/d * 190 +  dx/d * 130) * f2 * dt;
      }
    }

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.r += p.grow * dt;
  }
}

function drawSteam(){
  sctx.setTransform(1,0,0,1,0,0);
  sctx.clearRect(0,0,sc.width,sc.height);
  sctx.globalCompositeOperation = 'lighter';

  for(let i=0;i<puffs.length;i++){
    const p = puffs[i];
    const k = p.age / p.life;
    // fade in over the first 18%, long fade out
    const env = Math.min(1, k/0.18) * Math.pow(1-k, 1.5);
    if(env <= 0.002) continue;

    // cools (warm -> grey) with height above the rim
    const heat = clamp(1 - (cy*0.5 - p.y) / (rimRY*0.5 + R*0.9), 0, 1);
    const a = env * 0.20;
    const d = p.r * 2;
    const dx = p.x - p.r, dy = p.y - p.r;

    const w = heat * p.warm;
    if(w > 0.02){
      sctx.globalAlpha = a * w;
      sctx.drawImage(puffWarm, dx, dy, d, d);
    }
    if(w < 0.98){
      sctx.globalAlpha = a * (1 - w) * 0.85;
      sctx.drawImage(puffCool, dx, dy, d, d);
    }
  }
  sctx.globalAlpha = 1;
  sctx.globalCompositeOperation = 'source-over';

  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = 0.95;
  ctx.drawImage(sc, 0, 0, W, H);
  ctx.restore();
}

/* ============================== film grain ============================== */
let grainPat = null;
function buildGrain(){
  const s = 96;
  const c = document.createElement('canvas'); c.width = c.height = s;
  const x = c.getContext('2d');
  const img = x.createImageData(s,s);
  const d = img.data;
  for(let i=0;i<d.length;i+=4){
    const n = 110 + Math.floor(rnd()*90);
    d[i] = d[i+1] = d[i+2] = n;
    d[i+3] = 255;
  }
  x.putImageData(img,0,0);
  grainPat = ctx.createPattern(c,'repeat');
}

/* ============================== layout ============================== */
function layout(){
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  W = Math.max(1, window.innerWidth);
  H = Math.max(1, window.innerHeight);

  cvs.width  = Math.round(W * DPR);
  cvs.height = Math.round(H * DPR);
  cvs.style.width  = W + 'px';
  cvs.style.height = H + 'px';
  ctx.setTransform(DPR,0,0,DPR,0,0);

  sc.width  = Math.max(1, Math.round(W * 0.5));
  sc.height = Math.max(1, Math.round(H * 0.5));

  R = Math.min(W * 0.36, H * 0.33);
  rimRY = R * 0.355;
  cx = W * 0.5;
  cy = H * 0.575;

  bRX = R * BROTH_SCALE;
  bRY = rimRY * BROTH_SCALE;
  bcx = cx;
  bcy = cy + rimRY * B_OFF;

  if(!grainPat) buildGrain();

  if(!pointer.has){ pointer.x = pointer.tx = cx; pointer.y = pointer.ty = cy - rimRY*2; }
}

/* ============================== coordinate helpers ============================== */
const EX = u => cx + u * R;
const EY = v => cy + v * rimRY;

function bowlBodyPath(){
  ctx.beginPath();
  ctx.moveTo(cx - R, cy);
  ctx.bezierCurveTo(cx - R*1.03, cy + R*0.34, cx - R*0.79, cy + R*0.74, cx - R*0.38, cy + R*0.86);
  ctx.bezierCurveTo(cx - R*0.20, cy + R*0.915, cx + R*0.20, cy + R*0.915, cx + R*0.38, cy + R*0.86);
  ctx.bezierCurveTo(cx + R*0.79, cy + R*0.74, cx + R*1.03, cy + R*0.34, cx + R, cy);
  ctx.ellipse(cx, cy, R, rimRY, 0, 0, Math.PI);
  ctx.closePath();
}

/* ============================== painting ============================== */
function drawBackdrop(){
  const flick = reduced ? 1 : (1 + Math.sin(t*0.9)*0.045 + Math.sin(t*2.3+1.1)*0.025);

  ctx.fillStyle = '#050406';
  ctx.fillRect(0,0,W,H);

  const far = Math.max(W,H) * 0.95;
  const bg = ctx.createRadialGradient(cx, cy - rimRY*0.4, R*0.15, cx, cy, far);
  bg.addColorStop(0.00, '#191110');
  bg.addColorStop(0.35, '#100c0d');
  bg.addColorStop(0.72, '#08070a');
  bg.addColorStop(1.00, '#040305');
  ctx.fillStyle = bg;
  ctx.fillRect(0,0,W,H);

  ctx.save();
  ctx.globalCompositeOperation = 'lighter';

  // warm plume of light rising out of the bowl
  const gx = cx + lx * R * 0.22;
  const gy = cy - rimRY - R * 0.62 + ly * R * 0.10;
  const halo = ctx.createRadialGradient(gx, gy, 0, gx, gy, R * 2.5);
  halo.addColorStop(0.00, 'rgba(255,146,58,'+(0.115*flick).toFixed(4)+')');
  halo.addColorStop(0.32, 'rgba(214,96,32,'+(0.052*flick).toFixed(4)+')');
  halo.addColorStop(0.68, 'rgba(120,48,20,0.016)');
  halo.addColorStop(1.00, 'rgba(0,0,0,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(0,0,W,H);

  // cold counter-light from the far side, keeps the dark from going muddy
  const kx = cx - lx * R * 1.5, ky = cy - rimRY * 3.4;
  const cool = ctx.createRadialGradient(kx, ky, 0, kx, ky, R * 2.2);
  cool.addColorStop(0.00, 'rgba(74,104,150,0.055)');
  cool.addColorStop(1.00, 'rgba(0,0,0,0)');
  ctx.fillStyle = cool;
  ctx.fillRect(0,0,W,H);

  ctx.restore();
}

function drawTable(){
  // light spilling onto the surface around the bowl
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.translate(cx, cy + R*0.90);
  ctx.scale(1, 0.20);
  const pool = ctx.createRadialGradient(0,0,0,0,0,R*1.9);
  pool.addColorStop(0.00,'rgba(212,104,40,0.115)');
  pool.addColorStop(0.42,'rgba(150,66,26,0.045)');
  pool.addColorStop(1.00,'rgba(0,0,0,0)');
  ctx.fillStyle = pool;
  ctx.beginPath(); ctx.arc(0,0,R*1.9,0,TAU); ctx.fill();
  ctx.restore();

  // contact shadow
  ctx.save();
  ctx.translate(cx + lx*R*0.10, cy + R*0.93);
  ctx.scale(1, 0.19);
  const sh = ctx.createRadialGradient(0,0,R*0.10,0,0,R*1.25);
  sh.addColorStop(0.00,'rgba(0,0,0,0.86)');
  sh.addColorStop(0.45,'rgba(0,0,0,0.52)');
  sh.addColorStop(1.00,'rgba(0,0,0,0)');
  ctx.fillStyle = sh;
  ctx.beginPath(); ctx.arc(0,0,R*1.25,0,TAU); ctx.fill();
  ctx.restore();
}

function drawBowlBody(){
  bowlBodyPath();

  const g = ctx.createLinearGradient(cx - R*0.55, cy - rimRY, cx + R*0.5, cy + R*0.95);
  g.addColorStop(0.00,'#3a2f34');
  g.addColorStop(0.16,'#241d23');
  g.addColorStop(0.52,'#15111a');
  g.addColorStop(0.84,'#0c0912');
  g.addColorStop(1.00,'#08060d');
  ctx.fillStyle = g;
  ctx.fill();

  ctx.save();
  bowlBodyPath();
  ctx.clip();

  // glaze sheen down the key-light side
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.translate(cx + lx*R*0.52, cy + R*0.30);
  ctx.rotate(lx * 0.22);
  ctx.scale(1, 1.6);
  const sheen = ctx.createRadialGradient(0,0,0,0,0,R*0.44);
  sheen.addColorStop(0.00,'rgba(226,214,222,0.115)');
  sheen.addColorStop(0.55,'rgba(150,140,160,0.035)');
  sheen.addColorStop(1.00,'rgba(0,0,0,0)');
  ctx.fillStyle = sheen;
  ctx.beginPath(); ctx.arc(0,0,R*0.44,0,TAU); ctx.fill();
  ctx.restore();

  // broth-glow bleeding onto the ceramic just under the rim
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const warm = ctx.createLinearGradient(0, cy - rimRY*0.4, 0, cy + R*0.55);
  warm.addColorStop(0.00,'rgba(255,132,44,0.20)');
  warm.addColorStop(0.30,'rgba(198,82,28,0.075)');
  warm.addColorStop(1.00,'rgba(0,0,0,0)');
  ctx.fillStyle = warm;
  ctx.fillRect(cx-R*1.1, cy - rimRY*1.2, R*2.2, R*1.4);
  ctx.restore();

  // ceramic speckle
  for(let i=0;i<speckle.length;i++){
    const s = speckle[i];
    const x = cx + s.u * R * 0.96;
    const y = cy + s.y * R * 0.88;
    ctx.fillStyle = 'rgba(226,216,226,'+s.a+')';
    ctx.beginPath(); ctx.arc(x, y, s.r*R, 0, TAU); ctx.fill();
  }

  // deep shade at the base
  const base = ctx.createLinearGradient(0, cy + R*0.44, 0, cy + R*0.96);
  base.addColorStop(0,'rgba(0,0,0,0)');
  base.addColorStop(1,'rgba(0,0,0,0.62)');
  ctx.fillStyle = base;
  ctx.fillRect(cx-R*1.1, cy + R*0.40, R*2.2, R*0.62);

  ctx.restore();

  // edge rim-light around the silhouette
  bowlBodyPath();
  const el = ctx.createLinearGradient(cx - R, cy, cx + R, cy + R*0.7);
  const bright = 0.30 + lx * -0.10;
  el.addColorStop(0.00,'rgba(238,228,236,'+clamp(bright,0.08,0.42).toFixed(3)+')');
  el.addColorStop(0.30,'rgba(160,150,166,0.10)');
  el.addColorStop(0.62,'rgba(120,112,128,0.05)');
  el.addColorStop(1.00,'rgba(206,150,110,0.16)');
  ctx.strokeStyle = el;
  ctx.lineWidth = Math.max(0.8, R*0.010);
  ctx.stroke();
}

function drawInnerWall(){
  ctx.beginPath();
  ctx.ellipse(cx, cy, R, rimRY, 0, Math.PI, 0);
  ctx.ellipse(bcx, bcy, bRX, bRY, 0, 0, Math.PI, true);
  ctx.closePath();

  const g = ctx.createLinearGradient(0, cy - rimRY, 0, cy - rimRY*0.55);
  g.addColorStop(0.00,'#221a1c');
  g.addColorStop(0.55,'#3a2519');
  g.addColorStop(1.00,'#insertme');
  // (gradient stop fixed below)
  ctx.fillStyle = '#000';
  const g2 = ctx.createLinearGradient(0, cy - rimRY, 0, cy - rimRY*0.5);
  g2.addColorStop(0.00,'#1d1618');
  g2.addColorStop(0.50,'#3b2618');
  g2.addColorStop(1.00,'#6a3a15');
  ctx.fillStyle = g2;
  ctx.fill();
}

function drawBroth(){
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(bcx, bcy, bRX, bRY, 0, 0, TAU);
  ctx.clip();

  // body of the broth
  const gx = bcx - lx * bRX * 0.30;
  const gy = bcy - bRY * 0.42;
  const g = ctx.createRadialGradient(gx, gy, bRX*0.03, bcx, bcy, bRX*1.18);
  g.addColorStop(0.00,'#93511b');
  g.addColorStop(0.30,'#753c13');
  g.addColorStop(0.62,'#4d240c');
  g.addColorStop(0.86,'#2c1207');
  g.addColorStop(1.00,'#180a05');
  ctx.fillStyle = g;
  ctx.fillRect(bcx-bRX, bcy-bRY, bRX*2, bRY*2);

  // slow mottling in the stock
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for(let i=0;i<4;i++){
    const ph = i*1.7;
    const mx = bcx + Math.cos(t*0.16 + ph) * bRX * 0.34;
    const my = bcy + Math.sin(t*0.13 + ph*1.3) * bRY * 0.42;
    const mg = ctx.createRadialGradient(mx,my,0,mx,my,bRX*0.44);
    mg.addColorStop(0,'rgba(214,116,38,0.055)');
    mg.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle = mg;
    ctx.beginPath(); ctx.arc(mx,my,bRX*0.44,0,TAU); ctx.fill();
  }
  ctx.restore();

  // ripples
  for(let i=0;i<ripples.length;i++){
    const rp = ripples[i];
    const age = t - rp.t0;
    if(age < 0 || age > rp.life) continue;
    const k = age / rp.life;
    const rad = age * 0.46 * R;
    const a = (1-k) * (1-k) * 0.5 * rp.s;
    if(a < 0.004) continue;
    const px = EX(rp.u), py = EY(rp.v);
    ctx.lineWidth = Math.max(0.6, R*0.007);
    ctx.strokeStyle = 'rgba(255,206,150,'+(a*0.55).toFixed(4)+')';
    ctx.beginPath(); ctx.ellipse(px, py, rad, rad*0.36, 0, 0, TAU); ctx.stroke();
    ctx.strokeStyle = 'rgba(52,20,6,'+(a*0.42).toFixed(4)+')';
    ctx.beginPath(); ctx.ellipse(px, py, rad*0.90, rad*0.324, 0, 0, TAU); ctx.stroke();
    ctx.strokeStyle = 'rgba(255,180,110,'+(a*0.22).toFixed(4)+')';
    ctx.beginPath(); ctx.ellipse(px, py, rad*0.68, rad*0.245, 0, 0, TAU); ctx.stroke();
  }

  // broad specular sheen on the surface
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const shx = bcx + lx * bRX * 0.36 + Math.sin(t*0.4)*bRX*0.02;
  const shy = bcy + ly * bRY * 0.42;
  ctx.translate(shx, shy);
  ctx.rotate(-0.35);
  ctx.scale(1, 0.34);
  const sg = ctx.createRadialGradient(0,0,0,0,0,bRX*0.62);
  sg.addColorStop(0.00,'rgba(255,196,124,0.115)');
  sg.addColorStop(0.55,'rgba(255,150,70,0.035)');
  sg.addColorStop(1.00,'rgba(0,0,0,0)');
  ctx.fillStyle = sg;
  ctx.beginPath(); ctx.arc(0,0,bRX*0.62,0,TAU); ctx.fill();
  ctx.restore();

  drawOil();

  ctx.restore();

  // inner shadow where broth meets the wall
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(bcx, bcy, bRX, bRY, 0, 0, TAU);
  ctx.clip();
  ctx.lineWidth = R*0.10;
  ctx.strokeStyle = 'rgba(24,9,4,0.55)';
  ctx.beginPath(); ctx.ellipse(bcx, bcy, bRX, bRY, 0, 0, TAU); ctx.stroke();
  ctx.lineWidth = R*0.035;
  ctx.strokeStyle = 'rgba(255,168,92,0.10)';
  ctx.beginPath(); ctx.ellipse(bcx, bcy, bRX*0.995, bRY*0.995, 0, Math.PI*0.15, Math.PI*0.85); ctx.stroke();
  ctx.restore();
}

function drawOil(){
  for(let i=0;i<oils.length;i++){
    const o = oils[i];
    const drift = reduced ? 0 : Math.sin(t*o.sp + o.ph);
    const u = o.u + drift * 0.014;
    const v = o.v + Math.cos(t*o.sp*0.8 + o.ph)*0.010 + rippleAt(o.u,o.v)*0.7;
    const x = EX(u), y = EY(v);
    const rad = o.r * R;

    if(rad > R*0.012){
      const g = ctx.createRadialGradient(x - rad*0.30, y - rad*0.34, 0, x, y, rad);
      g.addColorStop(0.00,'rgba(255,214,146,0.50)');
      g.addColorStop(0.55,'rgba(236,150,58,0.26)');
      g.addColorStop(1.00,'rgba(126,58,16,0.05)');
      ctx.fillStyle = g;
    }else{
      ctx.fillStyle = 'rgba(248,178,92,0.30)';
    }
    ctx.beginPath(); ctx.ellipse(x, y, rad, rad*0.62, 0, 0, TAU); ctx.fill();

    ctx.strokeStyle = 'rgba(255,196,120,'+(0.22*o.sh).toFixed(3)+')';
    ctx.lineWidth = Math.max(0.4, rad*0.13);
    ctx.beginPath(); ctx.ellipse(x, y, rad*0.93, rad*0.58, 0, 0, TAU); ctx.stroke();

    ctx.fillStyle = 'rgba(255,242,214,'+(0.44*o.sh).toFixed(3)+')';
    ctx.beginPath();
    ctx.ellipse(x - rad*0.30 + lx*rad*0.12, y - rad*0.26, rad*0.22, rad*0.12, -0.5, 0, TAU);
    ctx.fill();
  }
}

/* ---------------------------- ingredients ---------------------------- */

function drawNoodles(){
  const N = 26;
  for(let s=0; s<noodles.length; s++){
    const nd = noodles[s];
    const sway = reduced ? 0 : Math.sin(t*nd.sp + nd.ph) * 0.012;
    const pts = [];
    for(let i=0;i<=N;i++){
      const k = i/N;
      const a = nd.a0 + nd.sweep * k;
      const m1 = 1 + nd.wob * Math.sin(a*nd.wf + nd.wp + t*0.28);
      const m2 = 1 + nd.wob * Math.sin(a*nd.wf + nd.wp + 1.7 - t*0.22);
      let u = nd.ou + nd.ru * m1 * Math.cos(a) + sway;
      let v = nd.ov + nd.rv * m2 * Math.sin(a);
      const c = containUV(u,v);
      u = c[0]; v = c[1] + rippleAt(c[0],c[1]) * 0.5;
      pts.push([EX(u), EY(v)]);
    }

    const lw = nd.w * R;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    // wet shadow beneath
    ctx.save();
    ctx.translate(0, lw*0.55);
    ctx.strokeStyle = 'rgba(46,18,4,0.50)';
    ctx.lineWidth = lw*1.05;
    strokePts(pts);
    ctx.restore();

    // body
    const grad = ctx.createLinearGradient(pts[0][0], pts[0][1] - lw, pts[pts.length-1][0], pts[pts.length-1][1] + lw);
    const warm = 0.72 + nd.tone*0.28;
    grad.addColorStop(0.00, 'rgba('+Math.round(232*warm)+','+Math.round(196*warm)+','+Math.round(126*warm)+',0.98)');
    grad.addColorStop(0.45, 'rgba('+Math.round(206*warm)+','+Math.round(160*warm)+','+Math.round(90*warm)+',0.98)');
    grad.addColorStop(1.00, 'rgba('+Math.round(158*warm)+','+Math.round(112*warm)+','+Math.round(56*warm)+',0.96)');
    ctx.strokeStyle = grad;
    ctx.lineWidth = lw;
    strokePts(pts);

    // specular thread along the top
    ctx.save();
    ctx.translate(lx*lw*0.16, -lw*0.24);
    ctx.strokeStyle = 'rgba(255,240,204,0.30)';
    ctx.lineWidth = lw*0.26;
    strokePts(pts);
    ctx.restore();
  }
}

function strokePts(pts){
  ctx.beginPath();
  ctx.moveTo(pts[0][0], pts[0][1]);
  for(let i=1;i<pts.length-1;i++){
    const xc = (pts[i][0] + pts[i+1][0]) / 2;
    const yc = (pts[i][1] + pts[i+1][1]) / 2;
    ctx.quadraticCurveTo(pts[i][0], pts[i][1], xc, yc);
  }
  ctx.lineTo(pts[pts.length-1][0], pts[pts.length-1][1]);
  ctx.stroke();
}

function waterline(x, y, w){
  ctx.save();
  ctx.globalCompositeOperation = 'multiply';
  const g = ctx.createRadialGradient(x,y,0,x,y,w);
  g.addColorStop(0,'rgba(40,16,4,0.85)');
  g.addColorStop(1,'rgba(40,16,4,0)');
  ctx.fillStyle = g;
  ctx.save();
  ctx.translate(x,y); ctx.scale(1,0.34);
  ctx.beginPath(); ctx.arc(0,0,w,0,TAU); ctx.fill();
  ctx.restore();
  ctx.restore();
}

function drawNori(){
  const u = -0.50, v = B_OFF - 0.50;
  const x = EX(u), y = EY(v);
  const w = R*0.44, h = R*0.50;
  const tilt = -0.16 + (reduced ? 0 : Math.sin(t*0.5)*0.020);

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(tilt);

  const g = ctx.createLinearGradient(-w/2, -h, w/2, h*0.4);
  g.addColorStop(0.00,'#14251f');
  g.addColorStop(0.35,'#0b1712');
  g.addColorStop(0.70,'#101d16');
  g.addColorStop(1.00,'#050b08');
  ctx.fillStyle = g;
  roundRect(-w/2, -h*0.72, w, h, R*0.018);
  ctx.fill();

  // pressed-seaweed striations
  ctx.save();
  roundRect(-w/2, -h*0.72, w, h, R*0.018);
  ctx.clip();
  for(let i=0;i<11;i++){
    const yy = -h*0.72 + (i+0.5)*(h/11);
    ctx.strokeStyle = i%2 ? 'rgba(150,200,178,0.045)' : 'rgba(0,0,0,0.30)';
    ctx.lineWidth = R*0.006;
    ctx.beginPath();
    ctx.moveTo(-w/2, yy + Math.sin(i*1.7)*R*0.006);
    ctx.bezierCurveTo(-w*0.15, yy - R*0.012, w*0.15, yy + R*0.012, w/2, yy);
    ctx.stroke();
  }
  // sheen
  ctx.globalCompositeOperation = 'lighter';
  const sg = ctx.createLinearGradient(-w*0.5, -h*0.7, w*0.2, h*0.1);
  sg.addColorStop(0.00,'rgba(168,214,196,0.10)');
  sg.addColorStop(0.40,'rgba(120,170,155,0.028)');
  sg.addColorStop(1.00,'rgba(0,0,0,0)');
  ctx.fillStyle = sg;
  ctx.fillRect(-w/2,-h*0.72,w,h);
  ctx.restore();

  // top edge catch-light
  ctx.strokeStyle = 'rgba(186,226,206,0.16)';
  ctx.lineWidth = Math.max(0.6, R*0.005);
  ctx.beginPath();
  ctx.moveTo(-w/2 + R*0.02, -h*0.72);
  ctx.lineTo(w/2 - R*0.02, -h*0.72);
  ctx.stroke();

  ctx.restore();
  waterline(x, y + h*0.26, w*0.62);
}

function roundRect(x,y,w,h,r){
  ctx.beginPath();
  ctx.moveTo(x+r,y);
  ctx.arcTo(x+w,y,x+w,y+h,r);
  ctx.arcTo(x+w,y+h,x,y+h,r);
  ctx.arcTo(x,y+h,x,y,r);
  ctx.arcTo(x,y,x+w,y,r);
  ctx.closePath();
}

function drawBokChoy(){
  const u = 0.02, v = B_OFF - 0.58;
  const bob = reduced ? 0 : Math.sin(t*0.7)*0.012;
  const x = EX(u), y = EY(v + bob);
  const s = R*0.30;

  ctx.save();
  ctx.translate(x,y);
  ctx.rotate(-0.10 + (reduced?0:Math.sin(t*0.55+1)*0.03));

  // stem
  const sg = ctx.createLinearGradient(-s*0.2,s*0.3,s*0.25,-s*0.2);
  sg.addColorStop(0,'#c9d8ad');
  sg.addColorStop(0.6,'#9fb681');
  sg.addColorStop(1,'#6f8a56');
  ctx.fillStyle = sg;
  ctx.beginPath();
  ctx.moveTo(-s*0.20, s*0.42);
  ctx.bezierCurveTo(-s*0.26, s*0.05, -s*0.20, -s*0.18, -s*0.06, -s*0.30);
  ctx.lineTo(s*0.16, -s*0.24);
  ctx.bezierCurveTo(s*0.12, s*0.02, s*0.16, s*0.28, s*0.20, s*0.44);
  ctx.closePath();
  ctx.fill();

  // leaf
  const lg = ctx.createLinearGradient(-s*0.4,-s*0.9, s*0.5, s*0.1);
  lg.addColorStop(0.00,'#4e7a3c');
  lg.addColorStop(0.40,'#2f5a2a');
  lg.addColorStop(0.80,'#1c3b1c');
  lg.addColorStop(1.00,'#132a15');
  ctx.fillStyle = lg;
  ctx.beginPath();
  ctx.moveTo(-s*0.05, -s*0.26);
  ctx.bezierCurveTo(-s*0.62, -s*0.44, -s*0.52, -s*1.02, -s*0.02, -s*1.06);
  ctx.bezierCurveTo(s*0.52, -s*1.02, s*0.58, -s*0.40, s*0.14, -s*0.22);
  ctx.closePath();
  ctx.fill();

  // veins + highlight
  ctx.strokeStyle = 'rgba(178,214,150,0.20)';
  ctx.lineWidth = Math.max(0.5, s*0.020);
  for(let i=-2;i<=2;i++){
    ctx.beginPath();
    ctx.moveTo(s*0.02, -s*0.30);
    ctx.quadraticCurveTo(s*i*0.14, -s*0.70, s*i*0.19, -s*0.94);
    ctx.stroke();
  }
  ctx.save();
  ctx.globalCompositeOperation='lighter';
  const hg = ctx.createRadialGradient(-s*0.16,-s*0.72,0,-s*0.16,-s*0.72,s*0.5);
  hg.addColorStop(0,'rgba(190,230,150,0.14)');
  hg.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle = hg;
  ctx.beginPath(); ctx.arc(-s*0.16,-s*0.72,s*0.5,0,TAU); ctx.fill();
  ctx.restore();

  ctx.restore();
  waterline(x, y + s*0.40, s*0.55);
}

function drawShiitake(u, v, sizeK, rot){
  const bob = reduced ? 0 : Math.sin(t*0.75 + u*6)*0.014;
  const rp  = rippleAt(u,v);
  const x = EX(u), y = EY(v + bob + rp*0.6);
  const s = R * sizeK;

  ctx.save();
  ctx.translate(x,y);
  ctx.rotate(rot + (reduced?0:Math.sin(t*0.5+v*4)*0.03));

  // cap
  const cg = ctx.createLinearGradient(-s*0.6,-s*0.5,s*0.5,s*0.3);
  cg.addColorStop(0.00,'#6b4529');
  cg.addColorStop(0.35,'#4e2f1b');
  cg.addColorStop(0.75,'#331d10');
  cg.addColorStop(1.00,'#20120a');
  ctx.fillStyle = cg;
  ctx.beginPath();
  ctx.moveTo(-s, s*0.10);
  ctx.bezierCurveTo(-s*0.94, -s*0.62, s*0.94, -s*0.62, s, s*0.10);
  ctx.bezierCurveTo(s*0.62, s*0.34, -s*0.62, s*0.34, -s, s*0.10);
  ctx.closePath();
  ctx.fill();

  // cross-hatched score on the cap
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(-s, s*0.10);
  ctx.bezierCurveTo(-s*0.94, -s*0.62, s*0.94, -s*0.62, s, s*0.10);
  ctx.bezierCurveTo(s*0.62, s*0.34, -s*0.62, s*0.34, -s, s*0.10);
  ctx.clip();
  ctx.strokeStyle = 'rgba(224,196,158,0.20)';
  ctx.lineWidth = Math.max(0.7, s*0.055);
  ctx.beginPath();
  ctx.moveTo(-s*0.44,-s*0.42); ctx.lineTo(s*0.34, s*0.22);
  ctx.moveTo( s*0.44,-s*0.42); ctx.lineTo(-s*0.34, s*0.22);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(0,0,0,0.30)';
  ctx.lineWidth = Math.max(0.5, s*0.03);
  ctx.beginPath();
  ctx.moveTo(-s*0.40,-s*0.36); ctx.lineTo(s*0.38, s*0.26);
  ctx.moveTo( s*0.40,-s*0.36); ctx.lineTo(-s*0.38, s*0.26);
  ctx.stroke();
  ctx.restore();

  // wet highlight
  ctx.save();
  ctx.globalCompositeOperation='lighter';
  const hg = ctx.createRadialGradient(-s*0.30 + lx*s*0.2, -s*0.30, 0, -s*0.30, -s*0.30, s*0.72);
  hg.addColorStop(0,'rgba(255,206,150,0.20)');
  hg.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle = hg;
  ctx.beginPath(); ctx.arc(-s*0.30,-s*0.30,s*0.72,0,TAU); ctx.fill();
  ctx.restore();

  ctx.restore();
  waterline(x, y + s*0.22, s*1.05);
}

function drawTofu(u, v, sizeK, rot){
  const bob = reduced ? 0 : Math.sin(t*0.65 + u*5)*0.013;
  const rp  = rippleAt(u,v);
  const x = EX(u), y = EY(v + bob + rp*0.7);
  const s = R * sizeK;

  ctx.save();
  ctx.translate(x,y);
  ctx.rotate(rot + (reduced?0:Math.sin(t*0.45+u*3)*0.025));

  const hw = s, hh = s*0.42, dp = s*0.62;

  // right face
  ctx.fillStyle = '#8a6c45';
  ctx.beginPath();
  ctx.moveTo(hw,0); ctx.lineTo(0,hh); ctx.lineTo(0,hh+dp); ctx.lineTo(hw,dp); ctx.closePath();
  ctx.fill();
  // left face
  ctx.fillStyle = '#a98a5c';
  ctx.beginPath();
  ctx.moveTo(-hw,0); ctx.lineTo(0,hh); ctx.lineTo(0,hh+dp); ctx.lineTo(-hw,dp); ctx.closePath();
  ctx.fill();
  // top face
  const tg = ctx.createLinearGradient(-hw,-hh,hw,hh);
  tg.addColorStop(0.00,'#f3e6c9');
  tg.addColorStop(0.45,'#e2cea4');
  tg.addColorStop(1.00,'#c8ad7d');
  ctx.fillStyle = tg;
  ctx.beginPath();
  ctx.moveTo(0,-hh); ctx.lineTo(hw,0); ctx.lineTo(0,hh); ctx.lineTo(-hw,0); ctx.closePath();
  ctx.fill();

  // seared edges
  ctx.strokeStyle = 'rgba(122,74,32,0.55)';
  ctx.lineWidth = Math.max(0.6, s*0.055);
  ctx.beginPath();
  ctx.moveTo(0,-hh); ctx.lineTo(hw,0); ctx.lineTo(0,hh); ctx.lineTo(-hw,0); ctx.closePath();
  ctx.stroke();

  // glaze on the top face
  ctx.save();
  ctx.globalCompositeOperation='lighter';
  const gg = ctx.createRadialGradient(-hw*0.25 + lx*hw*0.2, -hh*0.3, 0, 0, 0, hw);
  gg.addColorStop(0,'rgba(255,232,190,0.24)');
  gg.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle = gg;
  ctx.beginPath();
  ctx.moveTo(0,-hh); ctx.lineTo(hw,0); ctx.lineTo(0,hh); ctx.lineTo(-hw,0); ctx.closePath();
  ctx.fill();
  ctx.restore();

  ctx.restore();
  waterline(x, y + dp*0.75, s*1.15);
}

function drawCorn(){
  for(let i=0;i<corn.length;i++){
    const c = corn[i];
    const bob = reduced ? 0 : Math.sin(t*c.sp + c.ph)*0.012;
    const rp = rippleAt(c.u,c.v);
    const x = EX(c.u), y = EY(c.v + bob + rp*0.8);
    const s = c.r * R;

    ctx.save();
    ctx.translate(x,y);
    ctx.rotate(c.rot);
    const g = ctx.createLinearGradient(-s,-s*0.8,s*0.6,s*0.8);
    g.addColorStop(0.00,'#ffe08a');
    g.addColorStop(0.45,'#f2b845');
    g.addColorStop(1.00,'#a86f16');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-s*0.85,-s*0.10);
    ctx.bezierCurveTo(-s*0.85,-s*0.86, s*0.85,-s*0.86, s*0.85,-s*0.10);
    ctx.bezierCurveTo(s*0.85, s*0.72, -s*0.85, s*0.72, -s*0.85,-s*0.10);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = 'rgba(255,250,214,0.50)';
    ctx.beginPath();
    ctx.ellipse(-s*0.24 + lx*s*0.1, -s*0.34, s*0.24, s*0.16, -0.5, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(96,54,10,0.35)';
    ctx.lineWidth = Math.max(0.4, s*0.10);
    ctx.beginPath();
    ctx.moveTo(-s*0.5, s*0.34); ctx.quadraticCurveTo(0, s*0.56, s*0.5, s*0.34);
    ctx.stroke();
    ctx.restore();
  }
}

function drawScallions(){
  for(let i=0;i<scallions.length;i++){
    const s = scallions[i];
    const bob = reduced ? 0 : Math.sin(t*s.sp + s.ph)*0.016;
    const dft = reduced ? 0 : Math.sin(t*s.sp*0.4 + s.ph)*0.010;
    const rp = rippleAt(s.u,s.v);
    const x = EX(s.u + dft), y = EY(s.v + bob + rp);
    const r = s.r * R;

    ctx.save();
    ctx.translate(x,y);
    ctx.rotate(s.rot + (reduced?0:Math.sin(t*0.3+s.ph)*0.1));
    ctx.scale(1, 0.62);

    const light = 0.55 + s.tone*0.45;
    const g = ctx.createRadialGradient(-r*0.3,-r*0.3,r*0.1,0,0,r);
    g.addColorStop(0.00,'rgba('+Math.round(196*light)+','+Math.round(232*light)+','+Math.round(140*light)+',1)');
    g.addColorStop(0.70,'rgba('+Math.round(120*light)+','+Math.round(178*light)+','+Math.round(80*light)+',1)');
    g.addColorStop(1.00,'rgba('+Math.round(56*light)+','+Math.round(96*light)+','+Math.round(40*light)+',1)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(0,0,r,0,TAU); ctx.fill();

    // hollow centre
    ctx.fillStyle = 'rgba(48,28,10,0.72)';
    ctx.beginPath(); ctx.arc(0,0,r*0.40,0,TAU); ctx.fill();
    ctx.strokeStyle = 'rgba(226,246,190,0.32)';
    ctx.lineWidth = Math.max(0.4, r*0.13);
    ctx.beginPath(); ctx.arc(0,0,r*0.72,-2.5,-0.4); ctx.stroke();
    ctx.restore();
  }
}

function drawChilli(){
  ctx.save();
  // oily sheen under the crisp
  ctx.globalCompositeOperation = 'lighter';
  const px = EX(0.10), py = EY(B_OFF+0.44);
  const g = ctx.createRadialGradient(px,py,0,px,py,R*0.26);
  g.addColorStop(0,'rgba(226,74,22,0.16)');
  g.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.save(); ctx.translate(px,py); ctx.scale(1,0.42);
  ctx.beginPath(); ctx.arc(0,0,R*0.26,0,TAU); ctx.fill();
  ctx.restore();
  ctx.restore();

  for(let i=0;i<chilli.length;i++){
    const c = chilli[i];
    const bob = reduced ? 0 : Math.sin(t*c.sp + c.ph)*0.010;
    const rp = rippleAt(c.u,c.v);
    const x = EX(c.u), y = EY(c.v + bob + rp*0.9);
    const s = c.r * R;
    ctx.save();
    ctx.translate(x,y);
    ctx.rotate(c.rot + (reduced?0:Math.sin(t*0.4+c.ph)*0.15));
    const g2 = ctx.createLinearGradient(-s,-s,s,s);
    g2.addColorStop(0, c.hot > 0.55 ? '#ff7a2a' : '#d63c14');
    g2.addColorStop(1, '#7a1c07');
    ctx.fillStyle = g2;
    ctx.beginPath();
    ctx.ellipse(0,0,s,s*0.52,0,0,TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,206,150,0.30)';
    ctx.beginPath(); ctx.ellipse(-s*0.24,-s*0.16,s*0.28,s*0.14,-0.4,0,TAU); ctx.fill();
    ctx.restore();
  }
}

function drawSesame(){
  for(let i=0;i<sesame.length;i++){
    const s = sesame[i];
    const bob = reduced ? 0 : Math.sin(t*s.sp + s.ph)*0.014;
    const rp = rippleAt(s.u,s.v);
    const x = EX(s.u), y = EY(s.v + bob + rp);
    const r = R*0.011*s.s;
    ctx.save();
    ctx.translate(x,y);
    ctx.rotate(s.rot);
    ctx.fillStyle = 'rgba(242,226,192,0.92)';
    ctx.beginPath(); ctx.ellipse(0,0,r,r*0.58,0,0,TAU); ctx.fill();
    ctx.fillStyle = 'rgba(255,252,238,0.7)';
    ctx.beginPath(); ctx.ellipse(-r*0.22,-r*0.16,r*0.35,r*0.20,0,0,TAU); ctx.fill();
    ctx.restore();
  }
}

function drawIngredients(){
  drawNori();
  drawBokChoy();
  drawShiitake(0.46, B_OFF - 0.44, 0.145, -0.18);
  drawShiitake(0.66, B_OFF - 0.16, 0.125,  0.22);
  drawCorn();
  drawNoodles();
  drawTofu(0.48, B_OFF + 0.16, 0.115,  0.05);
  drawTofu(0.68, B_OFF + 0.40, 0.100, -0.08);
  drawChilli();
  drawScallions();
  drawSesame();
}

function drawRim(){
  // outer lip
  ctx.beginPath();
  ctx.ellipse(cx, cy, R, rimRY, 0, 0, TAU);
  const g = ctx.createLinearGradient(cx - R, cy - rimRY, cx + R, cy + rimRY);
  const l = clamp(0.5 - lx*0.22, 0.1, 0.9);
  g.addColorStop(0.00,'rgba(60,52,58,1)');
  g.addColorStop(clamp(l-0.18,0.02,0.9),'rgba(226,216,224,0.78)');
  g.addColorStop(clamp(l,0.05,0.95),'rgba(160,150,158,0.5)');
  g.addColorStop(1.00,'rgba(44,36,40,1)');
  ctx.strokeStyle = g;
  ctx.lineWidth = R*0.038;
  ctx.stroke();

  // thin bright edge
  ctx.beginPath();
  ctx.ellipse(cx, cy, R*1.001, rimRY*1.001, 0, 0, TAU);
  const g2 = ctx.createLinearGradient(cx - R, cy - rimRY, cx + R, cy + rimRY);
  g2.addColorStop(0.00,'rgba(255,255,255,0.06)');
  g2.addColorStop(clamp(l-0.15,0.02,0.9),'rgba(255,252,248,0.40)');
  g2.addColorStop(1.00,'rgba(255,190,130,0.14)');
  ctx.strokeStyle = g2;
  ctx.lineWidth = Math.max(0.7, R*0.007);
  ctx.stroke();

  // warm bounce along the inner front lip
  ctx.beginPath();
  ctx.ellipse(cx, cy, R*0.982, rimRY*0.982, 0, Math.PI*0.10, Math.PI*0.90);
  ctx.strokeStyle = 'rgba(255,158,74,0.16)';
  ctx.lineWidth = R*0.020;
  ctx.stroke();
}

function drawAtmosphere(){
  const flick = reduced ? 1 : (1 + Math.sin(t*1.7)*0.05 + Math.sin(t*0.6+2)*0.03);

  // bloom over the bowl mouth
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.translate(cx, cy - rimRY*0.15);
  ctx.scale(1, 0.55);
  const b = ctx.createRadialGradient(0,0,0,0,0,R*1.25);
  b.addColorStop(0.00,'rgba(255,152,66,'+(0.085*flick).toFixed(4)+')');
  b.addColorStop(0.45,'rgba(226,110,40,0.026)');
  b.addColorStop(1.00,'rgba(0,0,0,0)');
  ctx.fillStyle = b;
  ctx.beginPath(); ctx.arc(0,0,R*1.25,0,TAU); ctx.fill();
  ctx.restore();

  // vignette
  const v = ctx.createRadialGradient(cx, cy - rimRY*0.5, R*0.55, cx, cy, Math.max(W,H)*0.78);
  v.addColorStop(0.00,'rgba(0,0,0,0)');
  v.addColorStop(0.55,'rgba(0,0,0,0.30)');
  v.addColorStop(1.00,'rgba(0,0,0,0.86)');
  ctx.fillStyle = v;
  ctx.fillRect(0,0,W,H);

  // grain
  if(grainPat){
    ctx.save();
    ctx.globalCompositeOperation = 'overlay';
    ctx.globalAlpha = 0.055;
    const ox = reduced ? 0 : Math.floor(rnd()*96);
    const oy = reduced ? 0 : Math.floor(rnd()*96);
    ctx.translate(-ox,-oy);
    ctx.fillStyle = grainPat;
    ctx.fillRect(0,0,W+96,H+96);
    ctx.restore();
  }
}

/* ============================== frame ============================== */
function render(){
  drawBackdrop();
  drawTable();
  drawBowlBody();
  drawInnerWall();
  drawBroth();
  drawIngredients();
  drawRim();
  drawSteam();
  drawAtmosphere();
}

function update(dt){
  t += dt;

  // ease pointer + light
  const e = 1 - Math.pow(0.0015, dt);
  const px = pointer.x, py = pointer.y;
  pointer.x = lerp(pointer.x, pointer.tx, e);
  pointer.y = lerp(pointer.y, pointer.ty, e);
  pointer.vx = lerp(pointer.vx, (pointer.x - px)/Math.max(dt,1e-3), 1 - Math.pow(0.02, dt));
  pointer.vy = lerp(pointer.vy, (pointer.y - py)/Math.max(dt,1e-3), 1 - Math.pow(0.02, dt));

  const tlx = pointer.has ? clamp((pointer.x - cx) / (R*1.6), -1, 1) * 0.9 - 0.20 : -0.45;
  const tly = pointer.has ? clamp((pointer.y - cy) / (R*1.6), -1, 1) * 0.6 - 0.55 : -0.80;
  lx = lerp(lx, tlx, 1 - Math.pow(0.05, dt));
  ly = lerp(ly, tly, 1 - Math.pow(0.05, dt));

  // spontaneous ripples so the broth never sits still
  nextAuto -= dt;
  if(nextAuto <= 0){
    const p = inBroth(0.6);
    addRipple(p.u, p.v, rr(0.35,0.75));
    nextAuto = rr(1.8, 3.6);
  }

  for(let i=ripples.length-1;i>=0;i--){
    if(t - ripples[i].t0 > ripples[i].life) ripples.splice(i,1);
  }

  stepSteam(dt);
}

function loop(now){
  raf = requestAnimationFrame(loop);
  if(!last) last = now;
  let dt = (now - last) / 1000;
  last = now;
  if(dt > 0.05) dt = 0.05;   // keep the sim stable after a tab switch
  update(dt);
  render();
}

/* ============================== reduced motion ============================== */
function staticFrame(){
  t = 14.0;
  puffs.length = 0;
  ripples.length = 0;
  spawnAcc = 0;
  lx = -0.45; ly = -0.80;
  // settle the plume so the still frame already has steam in it
  for(let i=0;i<520;i++) stepSteam(1/60);
  render();
}

function start(){
  cancelAnimationFrame(raf);
  if(reduced){
    staticFrame();
  }else{
    last = 0;
    raf = requestAnimationFrame(loop);
  }
}

/* ============================== input ============================== */
let lastRippleAt = -1;
function onPointer(ev){
  if(reduced) return;
  pointer.has = true;
  pointer.tx = ev.clientX;
  pointer.ty = ev.clientY;

  // ripples where the pointer crosses the broth
  const u = (ev.clientX - cx) / R;
  const v = (ev.clientY - cy) / rimRY;
  const nu = u / BROTH_SCALE, nv = (v - B_OFF) / BROTH_SCALE;
  if(nu*nu + nv*nv < 1 && t - lastRippleAt > 0.28){
    lastRippleAt = t;
    addRipple(u, v, 1);
  }
}

window.addEventListener('pointermove', onPointer, {passive:true});
window.addEventListener('pointerdown', function(ev){
  if(reduced) return;
  onPointer(ev);
  const u = (ev.clientX - cx) / R;
  const v = (ev.clientY - cy) / rimRY;
  addRipple(u, v, 1.6);
}, {passive:true});
window.addEventListener('pointerleave', function(){ pointer.has = false; }, {passive:true});
window.addEventListener('blur', function(){ pointer.has = false; });

let resizeTO = 0;
window.addEventListener('resize', function(){
  clearTimeout(resizeTO);
  resizeTO = setTimeout(function(){
    layout();
    if(reduced) staticFrame();
  }, 90);
}, {passive:true});

if(mq.addEventListener){
  mq.addEventListener('change', function(e){ reduced = e.matches; start(); });
}else if(mq.addListener){
  mq.addListener(function(e){ reduced = e.matches; start(); });
}

document.addEventListener('visibilitychange', function(){
  if(document.hidden){ cancelAnimationFrame(raf); }
  else if(!reduced){ last = 0; raf = requestAnimationFrame(loop); }
});

/* ============================== go ============================== */
layout();
start();

})();
</script>
</body>
